import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { RawMaterialInward, RawMaterialInwardRequest } from '../pages/raw-material-inward/raw-material-inward';
import { environment } from '../environments/environments';

@Injectable({
  providedIn: 'root'
})
export class RawMaterialInwardService {
     private apiUrl = `${environment.apiUrl}/RawMaterialInward`; 
  constructor(private http: HttpClient) {}

  getInwards(): Observable<RawMaterialInward[]> {
    return this.http.get<RawMaterialInward[]>(this.apiUrl);
  }
  getInwardByID(id: number): Observable<RawMaterialInward> {
    return this.http.get<RawMaterialInward>(`${this.apiUrl}/${id}`)
  }
  addInward(Inward: RawMaterialInwardRequest): Observable<RawMaterialInwardRequest> {
  return this.http.post<RawMaterialInwardRequest>(`${this.apiUrl}/create`, Inward);
}

updateInward(id: number, Inward: RawMaterialInward): Observable<RawMaterialInward> {
  return this.http.put<RawMaterialInward>(`${this.apiUrl}/update/${id}`, Inward);
}

deleteInward(id: number): Observable<void> {
  
  return this.http.delete<void>(`${this.apiUrl}/${id}`);
}
  
}
